"use strict";

import fs from "node:fs";
import { randomUUID } from "node:crypto";
import constants from "../app/lib/constants/index.js";

// Rapid Consulting service pages (EN + available HI), generated by
// scripts/import-rapid-services.js from the handoff manuscripts.
const data = JSON.parse(
  fs.readFileSync(new URL("./data/rapid-services.json", import.meta.url), "utf8"),
);

// JSONB values are sent as JSON text so Postgres stores them as documents,
// not as SQL arrays.
const json = (value) => JSON.stringify(value ?? []);

export async function up({ context: queryInterface }) {
  const now = new Date();

  await queryInterface.sequelize.transaction(async (t) => {
    const services = data.map(({ translations, ...service }) => ({
      id: randomUUID(),
      code: service.code,
      slug: service.slug,
      type: service.type,
      family_code: service.family_code,
      icon: service.icon,
      pictures: json([]),
      related_codes: json(service.related_codes),
      legacy_urls: json(service.legacy_urls),
      sort_order: service.sort_order,
      is_active: service.is_active,
      created_at: now,
      updated_at: now,
    }));

    await queryInterface.bulkInsert(constants.models.SERVICE_TABLE, services, {
      transaction: t,
    });

    const translations = data.flatMap((service, index) =>
      service.translations.map((translation) => ({
        id: randomUUID(),
        service_id: services[index].id,
        locale: translation.locale,
        title: translation.title,
        h1: translation.h1,
        eyebrow: translation.eyebrow,
        short_description: translation.short_description,
        intro_html: translation.intro_html,
        sections: json(translation.sections),
        source_urls: json(translation.source_urls),
        status: translation.status,
        review_label: translation.review_label,
        meta_title: translation.meta_title,
        meta_description: translation.meta_description,
        meta_keywords: null,
        og_image: null,
        created_at: now,
        updated_at: now,
      })),
    );

    await queryInterface.bulkInsert(
      constants.models.SERVICE_TRANSLATION_TABLE,
      translations,
      { transaction: t },
    );
  });
}

export async function down({ context: queryInterface }) {
  // Translations are removed by ON DELETE CASCADE.
  await queryInterface.bulkDelete(constants.models.SERVICE_TABLE, {
    code: data.map((service) => service.code),
  });
}
